import{_ as o,o as r,c as s,a2 as e}from"./chunks/framework.CXsxtpvq.js";const n="/asset-studio/shots/03-jobs-setup-full.webp",a="/asset-studio/shots/04-jobs-preview.webp",i="/asset-studio/shots/06-queue.webp",m=JSON.parse('{"title":"이미지 생성","description":"","frontmatter":{},"headers":[],"relativePath":"ko/guide/generate.md","filePath":"ko/guide/generate.md"}'),l={name:"ko/guide/generate.md"};function d(g,t,p,c,h,u){return r(),s("div",null,[...t[0]||(t[0]=[e('<h1 id="이미지-생성" tabindex="-1">이미지 생성 <a class="header-anchor" href="#이미지-생성" aria-label="Permalink to &quot;이미지 생성&quot;">​</a></h1><p><strong>작업</strong> 메뉴에서 캐릭터 × 의상 × 감정 × 장수를 골라 한 번에 대기열에 넣습니다.</p><p><img src="'+n+'" alt="작업 화면 전체"></p><h2 id="순서" tabindex="-1">순서 <a class="header-anchor" href="#순서" aria-label="Permalink to &quot;순서&quot;">​</a></h2><ol><li><strong>작품</strong>을 고르고 왼쪽 목록에서 <strong>캐릭터</strong>를 체크합니다. 여러 명을 함께 골라도 됩니다.</li><li><strong>의상 세트</strong>를 체크합니다. 고른 캐릭터들이 쓸 수 있는 의상이 보입니다.</li><li><strong>넣을 부위</strong>를 확인합니다. 감정을 고르면 그 감정의 구도가 제안하는 부위가 자동으로 체크됩니다.</li><li><strong>감정·동작</strong>을 체크합니다. <strong>이 분류 전체 선택</strong>으로 한 번에 고를 수 있습니다.</li><li><strong>구도 · 화풍 · 공통</strong>에서 필요한 것을 체크합니다. 구도를 고르지 않으면 감정마다 정해 둔 구도를 씁니다.</li><li><strong>생성 설정</strong>에서 모델과 샘플러를 고르고 <strong>조합당 장수</strong>를 정합니다.</li><li>맨 아래 막대의 계산(캐릭터 × 의상 × 감정 × 장수)을 확인하고 <strong>N장 등록</strong>을 누릅니다.</li></ol><h2 id="생성-설정" tabindex="-1">생성 설정 <a class="header-anchor" href="#생성-설정" aria-label="Permalink to &quot;생성 설정&quot;">​</a></h2><p><strong>Anima</strong> / <strong>SDXL·IL</strong> 탭으로 모델 계열을 고릅니다. 계열을 바꾸면 그 계열에 맞는 모델과 조각만 보입니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>모델</td><td>확산 모델 또는 체크포인트. <code>[체크포인트]</code> 표시는 자체 텍스트 인코더가 있는 파인튜닝 모델입니다.</td></tr><tr><td>텍스트 인코더 · VAE · CLIP 유형</td><td>Anima일 때 필요합니다. 체크포인트형 파인튜닝은 그 모델의 텍스트 인코더를 고르세요.</td></tr><tr><td>샘플러 · 스케줄러 · Steps · CFG</td><td>ComfyUI와 같습니다.</td></tr><tr><td>가로 · 세로</td><td>LoRA 학습에 쓸 이미지라면 정사각형(예: 1536×1536)을 권합니다.</td></tr><tr><td>시드</td><td>-1이면 랜덤입니다. <strong>캐릭터별 고정 시드 사용</strong>을 켜면 한 번 등록할 때 캐릭터마다 시드 하나를 모든 이미지에 씁니다.</td></tr><tr><td>LoRA</td><td>직접 추가하는 LoRA입니다. 학습해서 등록한 LoRA는 <strong>등록된 LoRA 자동 적용</strong>이 켜져 있으면 저절로 들어갑니다.</td></tr></tbody></table><p>자주 쓰는 설정은 <strong>새 프리셋 저장</strong>으로 저장해 두고 <strong>설정 프리셋</strong>에서 불러옵니다. 감정 선택·구도· 화풍까지 함께 저장하려면 위쪽 <strong>조합 프리셋</strong>을 씁니다.</p><h2 id="미리보기" tabindex="-1">미리보기 <a class="header-anchor" href="#미리보기" aria-label="Permalink to &quot;미리보기&quot;">​</a></h2><p><strong>첫 번째 조합 미리보기</strong>의 <strong>미리보기</strong>를 누르면 첫 조합의 실제 프롬프트가 보입니다. 등록하기 전에 조각이 의도대로 이어졌는지 확인하세요. 자동 적용되는 LoRA가 있으면 여기에 &quot;자동 LoRA&quot;로 표시됩니다.</p><p><img src="'+a+'" alt="조합 미리보기"></p><ul><li><strong>워크플로 다운로드</strong>: 이 조합을 ComfyUI 워크플로 파일로 받습니다.</li><li><strong>이 설정으로 단일 생성</strong> / <strong>실험실에서 열기</strong>: 실험실로 넘겨 한 장만 생성하거나 설정을 바꿔 봅니다.</li><li><strong>이번 생성에서만 프롬프트 수정</strong>: 라이브러리 원본은 두고 이번 등록에만 프롬프트를 고칩니다.</li></ul><h2 id="대기열" tabindex="-1">대기열 <a class="header-anchor" href="#대기열" aria-label="Permalink to &quot;대기열&quot;">​</a></h2><p>등록하면 위쪽 대기열 버튼에 진행·대기 수가 보입니다. 버튼을 누르면 대기열 창이 열립니다.</p><p><img src="'+i+'" alt="대기열 창"></p><ul><li><strong>다음 작업부터 일시정지</strong>: 지금 생성 중인 이미지는 끝내고 멈춥니다.</li><li><strong>대기 작업 취소</strong>: 아직 시작하지 않은 작업을 모두 취소합니다.</li><li>작업 하나가 실패하면 대기열이 멈춥니다. 오류를 읽고 고친 뒤 다시 시작하세요.</li></ul><p>생성된 이미지는 <code>outputs/&lt;작품&gt;/&lt;캐릭터&gt;/&lt;의상&gt;/</code> 폴더에 <code>&lt;감정 코드&gt;.png</code>로 저장되고, 같은 감정을 다시 만들면 <code>_002</code>, <code>_003</code>처럼 번호가 붙습니다.</p>',18)])])}const b=o(l,[["render",d]]);export{m as __pageData,b as default};
